const EmojiPicker=dynamic(()=>import('./v2/EmojiPicker'),{ssr:false,loading:()=> <div className="emoji-loading" role="status">Opening emoji…</div>});

type Modal='verify'|'erase'|'auth'|'new'|'settings'|'timer'|'ai'|'incomingInvite'|null;
