 const draftRef=useRef(draft);draftRef.current=draft;
 const [recentEmoji,setRecentEmoji]=useState<string[]>([]),[skinTone,setSkinTone]=useState(0);
 const [selectedIds,setSelectedIds]=useState<string[]>([]),[messageAction,setMessageAction]=useState<MessageAction|null>(null),[editing,setEditing]=useState<ChatMessage|null>(null);
 const [phoneKeyboard,setPhoneKeyboard]=useState(false),[keyboardOpen,setKeyboardOpen]=useState(false);
 const savedComposition=useRef<{text:string;reply:ChatMessage|null;file:File|null;userId:string;peerId:string}|null>(null);
 const composerCursor=useRef({start:0,end:0,text:'',userId:'',peerId:'',revision:0});
 const selectedMessages=messages.filter(message=>selectedIds.includes(message.id)&&!message.system);
 const actionMessages=messageAction&&messageAction.userId===s.user?.id&&messageAction.peerId===s.activeId?messages.filter(message=>messageAction.ids.includes(message.id)&&!message.system):[];
 const forwardingContacts=s.conversations.filter(contact=>!contact.isBot&&!contact.blocked&&!contact.keyChanged&&contact.requestStatus!=='outgoing');
 const canDeleteEveryone=actionMessages.length>0&&actionMessages.every(message=>message.own&&!message.deleted&&!message.isBot&&!active?.isBot&&!['queued','sending','failed'].includes(message.status)&&(s.mode==='demo'||!!message.serverId));
 useEffect(()=>{const media=window.matchMedia('(pointer: coarse), (max-width: 760px)');const update=()=>{setPhoneKeyboard(media.matches);if(!media.matches)setKeyboardOpen(false)};update();media.addEventListener('change',update);return()=>media.removeEventListener('change',update)},[]);
 useEffect(()=>{setSelectedIds([]);setMessageAction(null);setEditing(null);savedComposition.current=null;setKeyboardOpen(false);composerCursor.current={start:0,end:0,text:'',userId:'',peerId:'',revision:composerCursor.current.revision+1}},[s.user?.id,s.activeId]);
 useEffect(()=>{setSelectedIds(previous=>{const kept=previous.filter(id=>messages.some(message=>message.id===id));return kept.length===previous.length?previous:kept});if(editing&&!messages.some(message=>message.id===editing.id&&!message.deleted))cancelEdit();if(reply){const latest=messages.find(message=>message.id===reply.id&&!message.deleted);if(!latest)setReply(null);else if(latest!==reply)setReply(latest)}},[messages,editing?.id,reply?.id]);
 function rememberCursor(){const area=textarea.current;if(area&&area.value===draftRef.current)composerCursor.current={start:area.selectionStart,end:area.selectionEnd,text:draftRef.current,userId:s.user?.id??'',peerId:s.activeId,revision:composerCursor.current.revision+1}}
 function currentCursor(){const cursor=composerCursor.current;if(cursor.userId===s.user?.id&&cursor.peerId===s.activeId&&cursor.text===draftRef.current)return cursor;const area=textarea.current;return{...cursor,start:area?.value===draftRef.current?area.selectionStart:draftRef.current.length,end:area?.value===draftRef.current?area.selectionEnd:draftRef.current.length}}
