 function beginEdit(message:ChatMessage){
  const current=useVeilnivo.getState();if(!s.user||current.user?.id!==s.user.id||current.activeId!==s.activeId||!message.own||message.deleted||active?.isBot)return;
  if(!editing)savedComposition.current={text:draftRef.current,reply,file,userId:s.user.id,peerId:s.activeId};
  setEditing(message);setReply(null);setFile(null);setEmoji(false);setSelectedIds([]);s.clearError();draftRef.current=message.text;setDraft(message.text);placeCaret(message.text.length);
 }
 function beginReply(message:ChatMessage){const current=useVeilnivo.getState();if(message.deleted||current.user?.id!==s.user?.id||current.activeId!==s.activeId)return;if(editing)cancelEdit();setReply(message);setEmoji(false);const userId=s.user?.id,peerId=s.activeId;requestAnimationFrame(()=>{const latest=useVeilnivo.getState();if(latest.user?.id===userId&&latest.activeId===peerId)textarea.current?.focus({preventScroll:true})})}
 function toggleSelected(id:string){setSelectedIds(previous=>previous.includes(id)?previous.filter(value=>value!==id):previous.length<50?[...previous,id]:previous)}
 function openMessageAction(kind:MessageAction['kind'],ids:string[]){const current=useVeilnivo.getState();if(!s.user||current.user?.id!==s.user.id||current.activeId!==s.activeId)return;typingComposer.current?.stop();setKeyboardOpen(false);setEmoji(false);s.clearError();setMessageAction({kind,ids,userId:s.user.id,peerId:s.activeId})}
 async function finishMessageAction(scope:'me'|'everyone'|string[]){const action=messageAction,current=useVeilnivo.getState();if(!action||current.busy||current.user?.id!==action.userId||current.activeId!==action.peerId)return;const ok=Array.isArray(scope)?await current.forwardMessages(action.ids,scope):await current.deleteMessages(action.ids,scope);const latest=useVeilnivo.getState();if(ok&&latest.user?.id===action.userId&&latest.activeId===action.peerId){setMessageAction(null);setSelectedIds([])}}
 useEffect(()=>{setRecentEmoji([]);setSkinTone(0)},[s.user?.id]);
