 const visible=s.conversations.filter(c=>(!c.isBot||s.preferences.aiEnabled)&&(filter==='all'||c.unread>0)&&(c.username.toLowerCase().includes(query.toLowerCase().replace(/^@/,''))||c.name.toLowerCase().includes(query.toLowerCase())));
 const displayMessages=useMemo(()=>messages.filter(m=>m.text.toLowerCase().includes(messageQuery.toLowerCase())||m.attachment?.name.toLowerCase().includes(messageQuery.toLowerCase())),[messages,messageQuery]);
 function choose(c:Conversation){typingComposer.current?.stop();s.selectChat(c.id);s.markRead(c.id);setMobileChat(true);setMessageQuery('');setChatSearch(false);setDraft('');setReply(null);setFile(null);setNav('messages');if(c.isBot&&!s.preferences.aiConsent)setModal('ai')}
