 async function send(){const atStart=useVeilnivo.getState();if(atStart.busy||atStart.user?.id!==s.user?.id||atStart.activeId!==s.activeId)return;if(editing){const id=editing.id,userId=s.user?.id,peerId=s.activeId,current=useVeilnivo.getState();if(current.user?.id!==userId||current.activeId!==peerId)return;const latest=current.messages[peerId]?.find(message=>message.id===id);if(!latest||latest.deleted||(latest.revision??0)!==(editing.revision??0)){useVeilnivo.setState({error:'This message changed on another device. Cancel editing and open its latest version.'});return}typingComposer.current?.stop();const ok=await s.editMessage(id,draftRef.current.trim());const afterEdit=useVeilnivo.getState();if(ok&&afterEdit.user?.id===userId&&afterEdit.activeId===peerId)cancelEdit();return}const latestDraft=draftRef.current;if(!latestDraft.trim()&&!file)return;typingComposer.current?.stop();if(active?.isBot&&!s.preferences.aiConsent){setModal('ai');return}const text=latestDraft.trim(),originalDraft=latestDraft,resultFile=file,replyId=reply?.id,peerId=s.activeId,userId=s.user?.id;const before=new Set((atStart.messages[peerId]||[]).map(m=>m.id));setEmoji(false);if(resultFile)await s.sendAttachment(resultFile,text,replyId);else await s.send(text,replyId);const after=useVeilnivo.getState();if(after.user?.id!==userId||after.activeId!==peerId)return;const enqueued=(after.messages[peerId]||[]).some(m=>m.own&&!before.has(m.id));if(enqueued){if(draftRef.current===originalDraft)draftRef.current='';setDraft(value=>value===originalDraft?'':value);setReply(value=>value?.id===replyId?null:value);setFile(value=>value===resultFile?null:value);if(textarea.current)textarea.current.style.height='26px'}textarea.current?.focus()}
 async function authenticate(e:React.FormEvent){e.preventDefault();if(authTab==='register')await s.register(username,password);else await s.login(username,password);const user=useVeilnivo.getState().user;if(user&&user.id!=='preview-cipher'){setPassword('');if(inviteToken)setModal('incomingInvite');else{setModal(null);window.history.replaceState({},'','/')}}}
 async function erase(){typingComposer.current?.stop();close();setDraft('');setPassword('');setFile(null);setReply(null);setAuthTab('login');window.history.replaceState({},'','/login/');await s.erase()}
 async function copy(value:string){try{await navigator.clipboard.writeText(value);setToast('Copied to clipboard')}catch{setToast('Clipboard unavailable. Select the text to copy it.')}}
 function selectFile(selected?:File){if(!selected)return;if(selected.size>10*1024*1024){setToast('Choose a file of 10 MB or less.');return}if(active?.isBot){setToast('Attachments are available in peer conversations.');return}setFile(selected);textarea.current?.focus()}
 const authForm=<><div className="auth-tabs"><button className={authTab==='register'?'selected':''} onClick={()=>setAuthTab('register')}>Create identity</button><button className={authTab==='login'?'selected':''} onClick={()=>setAuthTab('login')}>Sign in</button></div><form className="auth-form" onSubmit={authenticate}><label>Username<div className="username-field"><span>@</span><input aria-label="Username" placeholder="your_alias" autoComplete="username" value={username} onChange={e=>setUsername(e.target.value.toLowerCase().replace(/[^a-z0-9_]/g,''))} minLength={3} maxLength={24} required/></div></label><label>Password<input aria-label="Password" type="password" placeholder="At least 12 characters" value={password} onChange={e=>setPassword(e.target.value)} autoComplete={authTab==='register'?'new-password':'current-password'} minLength={12} required/></label><p className="form-note"><KeyRound size={14}/>Save your password. There is no recovery service.</p>{s.error&&<p className="form-error" role="alert">{s.error}</p>}<button className="primary-button" disabled={s.busy} type="submit">{s.busy?'Securing your identity…':authTab==='register'?'Create private identity':'Unlock Veilnivo'}<ArrowUpRight size={17}/></button></form><p className="local-notice">{s.mode==='demo'?'Local preview: identity and encrypted history stay in this browser.':'Your password never leaves this device.'}</p></>;
