 {modal==='new'&&<NewConversation key={s.user.id} initialTab={newTab} onClose={close} onOpened={()=>{setMobileChat(true);setNav('messages')}} onRequests={()=>{setMobileChat(true);setNav('requests')}}/>}
 {modal==='settings'&&<Settings onClose={close} onLock={lock} onIdentity={()=>{s.clearError();setAuthTab('register');setModal('auth')}} onPrivacy={()=>{close();setNav('security');setMobileChat(true)}}/>}
